const {THREE:T,RAPIER:R,sim,world,root,view}=game;
const rockets=[],fx=[];let cooldown=0,kick=0,serial=0;
const sphere=new T.SphereGeometry(1,12,8),bodyGeo=new T.CylinderGeometry(.065,.065,.52,10),noseGeo=new T.ConeGeometry(.085,.22,10);
const metal=new T.MeshStandardMaterial({color:0x687b39,metalness:.6,roughness:.35});
function puff(p,color,size,life,velocity){const m=new T.Mesh(sphere,new T.MeshBasicMaterial({color,transparent:true,opacity:1,depthWrite:false}));m.position.copy(p);m.scale.setScalar(size);root.add(m);fx.push({m,life,total:life,size,v:velocity||new T.Vector3()});}
function distanceBox(p,e){const c=e.id==='guard'?{x:sim.guard.x,y:sim.guard.y+.9,z:sim.guard.z}:e.position;return Math.hypot(Math.max(0,Math.abs(p.x-c.x)-e.half.x),Math.max(0,Math.abs(p.y-c.y)-e.half.y),Math.max(0,Math.abs(p.z-c.z)-e.half.z));}
function explode(p){const radius=1.25;let broken=0;for(const e of game.entities){if(e.removed||['ground','near-bank','far-bank','rooftop'].includes(e.id))continue;if(distanceBox(p,e)<=radius){game.removeEntity(e);broken++;}}
 const delta=new T.Vector3().copy(sim.position).sub(p),d=delta.length();if(d<3.5){delta.normalize().multiplyScalar((1-d/3.5)*7);delta.y+=2*(1-d/3.5);sim.player.applyImpulse(delta,true);}
 puff(p,0xffbf38,.2,.32);puff(p,0xff5015,.15,.48);
 for(let j=0;j<22;j++){const v=new T.Vector3(Math.random()-.5,Math.random()*.9,Math.random()-.5).normalize().multiplyScalar(2+Math.random()*4);puff(p,j%3?0x6b6b62:0xffd36a,.06+Math.random()*.09,.65+Math.random()*.4,v);}
 kick=Math.max(kick,.04);game.sound(70,.32,.13,23);game.say(broken?'Impact! Masonry and metal give way.':'Impact! Keep clear of the blast.');}
function removeRocket(i){rockets[i].mesh.removeFromParent();rockets.splice(i,1);}
return {use(){if(cooldown>0){game.say('Reloading…');return;}cooldown=.65;kick=.13;const d=new T.Vector3(sim.aim.x,sim.aim.y,sim.aim.z).normalize();if(d.lengthSq()<.5)d.set(1,0,0);
 const eye=new T.Vector3(sim.position.x,sim.position.y+.86,sim.position.z);const p=eye.clone().addScaledVector(d,.18);
 const mesh=new T.Group();mesh.name='Flying RPG rocket '+(++serial);const b=new T.Mesh(bodyGeo,metal),n=new T.Mesh(noseGeo,metal);n.position.y=.35;mesh.add(b,n);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d);mesh.position.copy(p);root.add(mesh);rockets.push({mesh,p,d,age:0,trail:0});puff(p,0xffe59a,.14,.1);game.sound(190,.16,.12,45);game.say('WHOOSH! Rocket away.');},
 step(dt){cooldown=Math.max(0,cooldown-dt);kick*=Math.exp(-15*dt);
 for(let i=rockets.length-1;i>=0;i--){const r=rockets[i];r.age+=dt;const travel=22*dt;const hit=world.castRay(new R.Ray(r.p,r.d),travel,true,undefined,undefined,undefined,sim.player);let dist=hit?hit.timeOfImpact:Infinity;
 if(sim.guardEnabled){const box=new T.Box3(new T.Vector3(sim.guard.x-.4,sim.guard.y,sim.guard.z-.4),new T.Vector3(sim.guard.x+.4,sim.guard.y+1.8,sim.guard.z+.4));const point=new T.Ray(r.p,r.d).intersectBox(box,new T.Vector3());if(point){const t=point.distanceTo(r.p);if(t<=travel)dist=Math.min(dist,t);}}
 if(dist<=travel){r.p.addScaledVector(r.d,dist);explode(r.p);removeRocket(i);continue;}r.p.addScaledVector(r.d,travel);r.mesh.position.copy(r.p);r.trail+=dt;if(r.trail>=.035){r.trail=0;puff(r.p.clone().addScaledVector(r.d,-.3),0x98978b,.075,.5);puff(r.p.clone().addScaledVector(r.d,-.28),0xffae32,.07,.09);}if(r.age>4)removeRocket(i);}
 for(let i=fx.length-1;i>=0;i--){const f=fx[i];f.life-=dt;if(f.life<=0){f.m.removeFromParent();f.m.material.dispose();fx.splice(i,1);continue;}f.m.position.addScaledVector(f.v,dt);f.v.y-=dt*2;const t=1-f.life/f.total;f.m.scale.setScalar(f.size*(1+4*t));f.m.material.opacity=(1-t)*.85;}
 },render(){const d=new T.Vector3(sim.aim.x,sim.aim.y,sim.aim.z).normalize();view.invention.quaternion.setFromUnitVectors(new T.Vector3(1,0,0),d);view.invention.position.set(sim.position.x,sim.position.y,sim.position.z).addScaledVector(d,-kick);},dispose(){for(const r of rockets)r.mesh.removeFromParent();for(const f of fx){f.m.removeFromParent();f.m.material.dispose();}rockets.length=0;fx.length=0;sphere.dispose();bodyGeo.dispose();noseGeo.dispose();metal.dispose();}};
